# LeetCode 1327 is SQL-only; Python equivalent using pandas-style logic:
class Solution:
    def productsOrdered(self, products: list[list[int]], orders: list[list]) -> list[tuple[str, int]]:
        from collections import defaultdict
        total = defaultdict(int)
        for pid, d, u in orders:
            if d.startswith('2020-02'):
                total[pid] += u
        name = {p[0]: p[1] for p in products}
        return [(name[pid], s) for pid, s in total.items() if s >= 100]

