// LeetCode 1327 is SQL-only; C++ equivalent:
class Solution {
public:
    vector<pair<string,int>> productsOrdered(vector<vector<int>>& products,
                                             vector<tuple<int,string,int>>& orders) {
        unordered_map<int,string> name;
        for (auto& p : products) name[p[0]] = "";
        unordered_map<int,long long> total;
        for (auto& [pid, d, u] : orders)
            if (d.rfind("2020-02", 0) == 0) total[pid] += u;
        vector<pair<string,int>> res;
        for (auto& p : products)
            if (total.count(p[0]) && total[p[0]] >= 100) res.push_back({"", (int)total[p[0]]});
        return res;
    }
};

