// LeetCode 1327 is SQL-only; Java equivalent:
class Solution {
    public List<String[]> productsOrdered(int[][] products, Object[][] orders) {
        Map<Integer, Long> total = new HashMap<>();
        for (Object[] o : orders) {
            String d = (String) o[1];
            if (d.startsWith("2020-02"))
                total.merge((Integer) o[0], ((Integer) o[2]).longValue(), Long::sum);
        }
        List<String[]> res = new ArrayList<>();
        for (int[] p : products)
            if (total.getOrDefault(p[0], 0L) >= 100)
                res.add(new String[]{String.valueOf(p[0]), String.valueOf(total.get(p[0]))});
        return res;
    }
}

