// LeetCode 1327 is SQL-only; JavaScript equivalent:
var productsOrdered = function(products, orders) {
    const total = new Map();
    for (const [pid, d, u] of orders)
        if (d.startsWith('2020-02')) total.set(pid, (total.get(pid) || 0) + u);
    return products.filter(p => (total.get(p[0]) || 0) >= 100)
                   .map(p => [p[0], total.get(p[0])]);
};
